/**
 * Bearer-token auth for the daemon-owned local side services.
 *
 * Phase 3 M1 (§5.3): the dev-browser relay (:9224) and the LLM proxies
 * (:9228/:9229) run on loopback without any auth today; any local process —
 * or any web page via DNS rebinding — can reach them. Each side service now
 * requires a per-process bearer token that is generated by the spawning side
 * (daemon / task bootstrap) and distributed via env / generated task config —
 * never via RPC and never via the gateway.
 *
 * Mirrors apps/host/src/auth.ts (same timing-safe comparison; kept as a
 * separate daemon-side module so the host gateway policy stays canonical).
 */

import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';

const TOKEN_BYTES = 32;

/** Generate a per-process side-service token (256-bit, base64url). */
export function generateServiceToken(): string {
  return randomBytes(TOKEN_BYTES).toString('base64url');
}

/**
 * Constant-time string comparison. Both sides are hashed first so inputs of
 * different lengths cannot leak length information through an early exit.
 * Empty inputs never compare equal — an empty presented token must never
 * authenticate, whatever the configuration state.
 */
export function timingSafeTokenEquals(a: string, b: string): boolean {
  if (a.length === 0 || b.length === 0) {
    return false;
  }
  const ha = createHash('sha256').update(a).digest();
  const hb = createHash('sha256').update(b).digest();
  return timingSafeEqual(ha, hb);
}

export function extractBearerToken(header: string | undefined): string | null {
  if (!header) {
    return null;
  }
  const [scheme, value] = header.split(' ', 2);
  if (scheme?.toLowerCase() !== 'bearer' || !value) {
    return null;
  }
  return value.trim();
}

/**
 * Verify a request bearer token against the allowlist of tokens the service
 * currently accepts. Returns false for a missing/empty presented token.
 */
export function verifyBearerToken(
  presentHeader: string | undefined,
  validTokens: ReadonlySet<string>,
): boolean {
  const presented = extractBearerToken(presentHeader);
  if (!presented) {
    return false;
  }
  // Set is small (≤ a few per-process tokens) — linear scan stays timing-OK
  // because each comparison itself is constant-time over hashed digests.
  for (const expected of validTokens) {
    if (timingSafeTokenEquals(presented, expected)) {
      return true;
    }
  }
  return false;
}

/**
 * Verify a dedicated header that carrys the raw token value (no "Bearer "
 * prefix). The proxy surfaces use this for the `x-accomplish-proxy-token`
 * header because `Authorization` stays reserved for the real upstream
 * credential. Returns false for a missing/empty value.
 */
export function verifyRawToken(
  headerValue: string | undefined,
  validTokens: ReadonlySet<string>,
): boolean {
  // Array-valued header (duplicates) never matches — take the last value.
  const presented = typeof headerValue === 'string' ? headerValue.trim() : '';
  if (presented.length === 0) {
    return false;
  }
  for (const expected of validTokens) {
    if (timingSafeTokenEquals(presented, expected)) {
      return true;
    }
  }
  return false;
}

/**
 * Fixed token-holder for a single-token surface (dev-browser sidecar): the
 * allowlist contains exactly one expected value. Returns false for a
 * missing/empty presented token.
 */
export function verifyBearerTokenEquals(
  presentHeader: string | undefined,
  expected: string,
): boolean {
  const presented = extractBearerToken(presentHeader);
  return !!presented && timingSafeTokenEquals(presented, expected);
}

/**
 * Standard Authorization header value for a surface token, e.g.
 * `Authorization: Bearer ${token}`.
 */
export function bearerHeaderValue(token: string): string {
  return `Bearer ${token}`;
}
